export default ({
  name,
  color,
  size = 24,
  spin,
  style = {},
}: {
  name: string;
  color?: string;
  size?: number;
  spin?: {
    duration: number;
    outputRange: string[];
    delay: number;
    easing: any;
  };
  style?: any;
}) => {
  const theme = useSelector(memoizedGetTheme);
  const spinValue = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (spin?.outputRange) {
      const spinAnimation = Animated.sequence([
        Animated.timing(spinValue, {
          toValue: 1,
          duration: spin?.duration, // Rotate 120 degrees in 1 second
          easing: spin?.easing === 'linear' ? Easing.linear : Easing.elastic(1),
          useNativeDriver: true,
        }),
        Animated.delay(spin?.delay), // 4 second delay
      ]);

      Animated.loop(spinAnimation).start();
    }
  }, [spin, spinValue]);

  const spinAnimation = spin?.outputRange
    ? spinValue.interpolate({
        inputRange: [0, 1],
        outputRange: spin?.outputRange, // Rotate 120 degrees
      })
    : '0deg';

  return (
    <Animated.View
      style={{
        transform: [{ rotate: spinAnimation }],
        ...style,
      }}>
      <Icon name={name} size={size} color={color || greys(theme)[0]} />
    </Animated.View>
  );
};

